package de.buw.fmp.alloy.browser.teavm;

import java.util.Objects;
import org.teavm.model.MethodHolder;
import org.teavm.model.ValueType;
import org.teavm.model.emit.ProgramEmitter;

/**
 * Replaces the body of every method {@code className.methodName} (all overloads) with code
 * generated by {@link Body}. Applied by {@link MethodPatchTransformer} while TeaVM loads classes.
 */
final class MethodPatch {

  /** Generates the replacement body into a fresh program. */
  @FunctionalInterface
  interface Body {
    void emit(ProgramEmitter pe, MethodHolder method);
  }

  final String className;
  final String methodName;
  final Body body;

  private MethodPatch(String className, String methodName, Body body) {
    this.className = Objects.requireNonNull(className);
    this.methodName = Objects.requireNonNull(methodName);
    this.body = Objects.requireNonNull(body);
  }

  /** Arbitrary replacement body. */
  static MethodPatch replace(String className, String methodName, Body body) {
    return new MethodPatch(className, methodName, body);
  }

  /**
   * {@code throw new UnsupportedOperationException(feature + " is not available ...")}.
   */
  static MethodPatch unsupported(String className, String methodName, String feature) {
    String message = feature + " is not available in the browser engine";
    return new MethodPatch(
        className,
        methodName,
        (pe, method) ->
            pe.construct(UnsupportedOperationException.class, pe.constant(message)).raise());
  }

  /** Empty body; only valid for {@code void} methods and initializers. */
  static MethodPatch noop(String className, String methodName) {
    return new MethodPatch(
        className,
        methodName,
        (pe, method) -> {
          if (method.getResultType() != ValueType.VOID) {
            throw new IllegalStateException("noop patch on non-void " + method.getReference());
          }
          pe.exit();
        });
  }

  /** {@code return null}. */
  static MethodPatch returnNull(String className, String methodName) {
    return new MethodPatch(
        className,
        methodName,
        (pe, method) -> pe.constantNull(method.getResultType()).returnValue());
  }

  /** {@code return Owner.FIELD}. */
  static MethodPatch returnStaticField(
      String className, String methodName, String fieldOwner, String fieldName) {
    return new MethodPatch(
        className,
        methodName,
        (pe, method) ->
            pe.getField(fieldOwner, fieldName, ValueType.object(fieldOwner))
                .cast(method.getResultType())
                .returnValue());
  }
}
